<?php declare(strict_types=1);require dirname(__DIR__).'/_bootstrap.php';require_get();$user=api_user();api_rate_limit($user,'wallet.balance',60,60);$stmt=db()->prepare('SELECT w.balance,w.bonus_balance,w.promo_balance,w.bonus_expires_at,w.promo_expires_at,w.currency,w.status,w.updated_at,u.balance_privacy_enabled privacy_mode FROM wallets w JOIN users u ON u.id=w.user_id WHERE w.user_id=?');$stmt->execute([$user['id']]);$wallet=$stmt->fetch();if(!$wallet)json_response(false,'Wallet not found',null,404);$wallet['privacy_mode']=(bool)$wallet['privacy_mode'];$wallet['withdrawable_balance']=$wallet['balance'];json_response(true,'Wallet retrieved',$wallet);
